insert into public.products (id, data) values
  ('bw-smart', '{"id":"bw-smart","name":"Умная салфетка","cat":"Микрофибра","price":340,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["2 шт · 50×40 см"],"desc":"Гладкая, как замша, салфетка без ворса: полирует стекло и глянец до блеска и не оставляет разводов. Не становится склизкой, когда намокает.\nДля окон, зеркал и душевой, экранов, очков и оптики, хрома, фасадов кухни и салона машины. Сухой собирает пыль, влажной убирает пятна и отпечатки — обычно хватает одной воды.\nМногоразовая: прополоскали, высушили — и снова в деле. Милый полезный подарок для хозяйки.","comp":"Нетканая микрофибра, безворсовая","specs":"2 шт · 50×40 см","care":"После уборки прополоскать и высушить. Стирать без кондиционера и отбеливателя.","photos":[{"src":"img/bw-smart_5.jpg","color":""},{"src":"img/bw-smart_1.jpg","color":""},{"src":"img/bw-smart_2.jpg","color":""},{"src":"img/bw-smart_3.jpg","color":""},{"src":"img/bw-smart_4.jpg","color":""}],"params":[],"stock":{"Стандарт|2 шт · 50×40 см":4}}'::jsonb),
  ('bw-four', '{"id":"bw-four","name":"Тряпочки «Ракушка», 4 шт","cat":"Микрофибра","price":350,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["4 шт · 35×35 см"],"desc":"Плотные мягкие тряпочки двух фактур: объёмная «ракушка» собирает воду, жир и крошки и оттирает засохшие пятна, гладкая в мелкий рубчик полирует стекло, зеркала и смесители без разводов.\nВ наборе 2 розовые и 2 цвета мокко — удобно разделить: одни для кухни, другие для ванной или машины. Работают одной водой, без химии.\nВыдерживают до 100 стирок, край не сыплется. Нежная замена старым кухонным тряпкам.","comp":"80% полиэстер, 20% полиамид, 300 г/м²","specs":"4 шт · 35×35 см","care":"Прополоскать и просушить после уборки. Стирать до 60 °C отдельно от хлопка, без кондиционера и отбеливателя. Не кипятить и не гладить.","photos":[{"src":"img/bw-four_3.jpg","color":""},{"src":"img/bw-four_1.jpg","color":""},{"src":"img/bw-four_2.jpg","color":""},{"src":"img/bw-four_4.jpg","color":""},{"src":"img/bw-four_5.jpg","color":""},{"src":"img/bw-four_6.jpg","color":""},{"src":"img/bw-four_7.jpg","color":""}],"params":[],"stock":{"Стандарт|4 шт · 35×35 см":6}}'::jsonb),
  ('bw-wave', '{"id":"bw-wave","name":"Микрофибра в рулоне","cat":"Микрофибра","price":300,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["20 шт · 25×25 см"],"desc":"Мягкие салфетки с волнистым краем в удобном рулоне: оторвали по перфорации сколько нужно — и за уборку.\nХорошо впитывают воду, снимают жир, пыль и отпечатки без ворса и разводов и не царапают покрытия. Для посуды, столов и плиты, стёкол, зеркал, техники и машины — сухими и влажными.\nМногоразовые и заменяют десятки бумажных полотенец.","comp":"Микрофибра","specs":"20 шт · 25×25 см","care":"После уборки прополоскать и высушить. Стирать без кондиционера и отбеливателя.","photos":[{"src":"img/bw-wave_7.jpg","color":""},{"src":"img/bw-wave_1.jpg","color":""},{"src":"img/bw-wave_2.jpg","color":""},{"src":"img/bw-wave_3.jpg","color":""},{"src":"img/bw-wave_4.jpg","color":""},{"src":"img/bw-wave_5.jpg","color":""},{"src":"img/bw-wave_6.jpg","color":""},{"src":"img/bw-wave_8.jpg","color":""},{"src":"img/bw-wave_9.jpg","color":""},{"src":"img/bw-wave_10.jpg","color":""}],"params":[],"stock":{"Стандарт|20 шт · 25×25 см":7}}'::jsonb),
  ('bw-lintfree', '{"id":"bw-lintfree","name":"Безворсовые салфетки, 100 шт","cat":"Салфетки в рулоне","price":330,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["100 шт · 30×25 см"],"desc":"Та самая салфетка для кухни: плотная, мягкая, без ворса и разводов. Впитывает в 2 раза больше своего веса.\nРазмер 30×25 см больше обычного — протираете большую поверхность за один раз. Отрывается по перфорации, после уборки достаточно прополоскать — и она снова как новая.\nДля кухни, ванной, мебели, стёкол, техники и машины; гипоаллергенные, подходят и для ухода за кожей.","comp":"Нетканый материал повышенной плотности","specs":"100 шт · 30×25 см","care":"После использования прополоскать и расправить для сушки.","photos":[{"src":"img/bw-lintfree_2.jpg","color":""},{"src":"img/bw-lintfree_1.jpg","color":""},{"src":"img/bw-lintfree_3.jpg","color":""},{"src":"img/bw-lintfree_4.jpg","color":""},{"src":"img/bw-lintfree_5.jpg","color":""},{"src":"img/bw-lintfree_6.jpg","color":""}],"params":[],"stock":{"Стандарт|100 шт · 30×25 см":6}}'::jsonb),
  ('bw-foam', '{"id":"bw-foam","name":"Пенящиеся салфетки, 30 шт","cat":"Салфетки в рулоне","price":320,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["30 шт · 42×26 см"],"desc":"Двусторонние: абразивная сторона для застаревших пятен, мягкая — для деликатной уборки. Кокосовая пропитка с мятой и витамином Е мягко пенится при первом намокании — средство для мытья почти не нужно.\nБольшой размер 42×26 см и плотность 85 г/м²: прочные, не оставляют ворса и царапин, бережны к рукам.\nДля кухни, ванной, мебели, стёкол, техники и машины. Многоразовые.","comp":"Нетканый материал 85 г/м², пропитка: кокос, мята, витамин Е","specs":"30 шт · 42×26 см","care":"Прополоскать после уборки и просушить. Можно стирать.","photos":[{"src":"img/bw-foam_5.jpg","color":""},{"src":"img/bw-foam_1.jpg","color":""},{"src":"img/bw-foam_2.jpg","color":""},{"src":"img/bw-foam_3.jpg","color":""},{"src":"img/bw-foam_4.jpg","color":""}],"params":[],"stock":{"Стандарт|30 шт · 42×26 см":8}}'::jsonb),
  ('bw-scrub', '{"id":"bw-scrub","name":"Скраббер-салфетки","cat":"Скрабберы","price":310,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["Пачка, листовые"],"desc":"Жёсткие листовые скрабберы для сложных загрязнений: легко снимают жир, нагар и пригоревшее с посуды, плиты, кастрюль и сковородок, кафеля и раковины.\nНе впитывают воду и не размокают — остаются жёсткими всю уборку и не царапают. С моющим средством дают густую пену.\nКомпактная пачка: достаёте по одному листу. Отлично работают в паре с безворсовыми салфетками BiWabi.","comp":"Абразивный нетканый материал","specs":"Пачка, листовые","care":"Промыть после использования и просушить.","photos":[{"src":"img/bw-scrub_2.jpg","color":""},{"src":"img/bw-scrub_1.jpg","color":""},{"src":"img/bw-scrub_3.jpg","color":""},{"src":"img/bw-scrub_4.jpg","color":""}],"params":[],"stock":{"Стандарт|Пачка, листовые":3}}'::jsonb),
  ('bw-bamboo', '{"id":"bw-bamboo","name":"Бамбуковые салфетки, 65 шт","cat":"Салфетки в рулоне","price":300,"oldPrice":0,"hidden":false,"freeShip":false,"isNew":false,"brand":"biwabi","colors":["Стандарт"],"sizes":["65 шт · 25×25 см"],"desc":"Плотные нетканые салфетки из бамбукового волокна — заботливая замена бумажным полотенцам: одна салфетка служит как до семи бумажных.\nХорошо впитывают, убирают без разводов, не царапают. Для стола, плиты и вытяжки, стёкол и зеркал, салона машины, а ещё чтобы промокнуть овощи, мясо и лишний жир.\nРассчитаны на несколько применений, затем утилизируются — всегда свежие и гигиеничные.","comp":"80% бамбуковое волокно, 20% полипропилен, 80 г/м²","specs":"65 шт · 25×25 см","care":"Не стирать: после нескольких применений заменить свежей салфеткой.","photos":[{"src":"img/bw-bamboo_1.jpg","color":""},{"src":"img/bw-bamboo_2.jpg","color":""},{"src":"img/bw-bamboo_3.jpg","color":""}],"params":[],"stock":{"Стандарт|65 шт · 25×25 см":3}}'::jsonb)
